import os

def read_file(root: str, name: str):
    root_resolved = os.path.realpath(root)
    target = os.path.realpath(os.path.join(root_resolved, name))
    if not os.path.commonpath([root_resolved, target]).startswith(root_resolved) and target != root_resolved:
        raise ValueError("path escapes root")
    if target != root_resolved and not target.startswith(root_resolved + os.sep):
        raise ValueError("path escapes root")
    with open(target) as f:
        return f.read()

